INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6d4c4a81-4b55-4f18-ae09-08f590b25936', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$31. óra: A törtek szorzását alkalmazó feladatok megoldása$q$, $q$Törtrész kiszámítása és szöveges feladatok megoldása szorzással.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "a9e38edb-e22b-46ec-837f-e74da3d6be67", "text": "Mennyi 60-nak a 3/4 része? (60 * 3/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "fb1ab50f-1907-44a0-a978-42d46f6878d3", "text": "Mennyi 100-nak az 1/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "4f28df29-5822-4db9-b162-a5c2516fae69", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szeletet ettek meg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "ade08027-3f14-43ad-9682-9070ef9ae673", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szelet maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "71988521-ee0e-4533-823a-39feeef2dd49", "text": "Egy szám törtrészének kiszámításához a számot megszorozzuk a törttel.", "type": "true-false", "options": [{"id": "1a803052-53cf-492c-8d14-895c49f0257e", "text": "Igaz", "isCorrect": true}, {"id": "3e2eab2a-0a48-493f-9761-42dffa8f96bf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "399aa1be-450c-47cf-8a31-59255f709be1", "text": "Mennyi 50-nek a 2/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "2e437803-0415-48be-a980-14f3772bded9", "text": "Mennyi 1/2 óra percekben? (60 * 1/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d52b57e4-9fc4-4f1d-bc63-ccbbb3d5024e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$32. óra: Osztás törttel$q$, $q$Törttel való osztás szabálya: szorzás a reciprokával.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "82d85bfa-05d9-4077-8371-40460576fdfc", "text": "Hogyan osztunk törttel?", "type": "multiple-choice", "options": [{"id": "62471389-8bb9-4b4e-8276-3a4ff48f5447", "text": "Az osztandót megszorozzuk az osztó reciprokával", "isCorrect": true}, {"id": "facae8a7-268c-4cab-b2c1-a5cd352a32f1", "text": "Az osztandót elosztjuk a nevezővel", "isCorrect": false}, {"id": "cf18fa5a-3cf4-4360-b397-ef1ae2a0b933", "text": "Mindig 1-et kapunk", "isCorrect": false}, {"id": "f1693ad9-5190-46f2-bb6e-33098a3a98b4", "text": "A számlálókat elosztjuk egymással", "isCorrect": false}], "timeLimit": 15}, {"id": "c4b6a40c-a570-409a-a3e8-eab300fb82db", "text": "Mennyi 2/3 : 4/5? (2/3 * 5/4)", "type": "multiple-choice", "options": [{"id": "1f988eef-4bbe-407a-9be0-39f303ddf684", "text": "10/12 (azaz 5/6)", "isCorrect": true}, {"id": "c96930c3-9202-4a19-a874-22ac73624943", "text": "8/15", "isCorrect": false}, {"id": "5fe2df75-bf69-4be6-bfa0-2deed4ef14e5", "text": "6/8", "isCorrect": false}, {"id": "7b217e20-1fb0-4a1c-9a72-adc130a854eb", "text": "15/8", "isCorrect": false}], "timeLimit": 15}, {"id": "eba7ab64-5eb2-4ab1-9f76-15e7b5f9177a", "text": "Mennyi 1/2 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "a9c3686e-930b-4342-8208-621b79bc3eae", "text": "Ha egy számot 1/2-del osztunk, az eredmény megegyezik a szám 2-vel való szorzatával.", "type": "true-false", "options": [{"id": "59ebdbda-68c9-4e61-8ff7-c9c9be555bc2", "text": "Igaz ( : 1/2 = * 2)", "isCorrect": true}, {"id": "26bb34a3-c6bb-4f0c-8300-884185b9661a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1eb16c8b-fec4-4e2c-8075-0b62120bab21", "text": "Mennyi 6 : 1/3? (6 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "a107c782-e4fb-437c-970f-9648af5da72e", "text": "Törttel való osztáskor az osztandó nem változik, csak az osztót fordítjuk meg.", "type": "true-false", "options": [{"id": "ea9d5be1-8960-4b58-b0fd-e58fb283dc7b", "text": "Igaz", "isCorrect": true}, {"id": "5eede5b3-1033-448d-8ca2-d6be58351b4b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a8388c6e-acc8-476f-9d77-9e4e819b377e", "text": "Mennyi 3/4 : 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ad1b69a4-72d0-4e55-94ca-3ca167343b95', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$33. óra: Hétköznapi problémák megoldása törtek osztásának felhasználásával$q$, $q$Szöveges feladatok mérésekkel, átdarabolásokkal, törtek osztásával.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "cf213823-4ec5-476c-9aea-696c50422770", "text": "Hány 1/4 literes pohár tölthető meg 3 liter almaléből? (3 : 1/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "824e73cf-88f2-4dd8-8af0-22bec2c252fa", "text": "Hány 1/2 kg-os csomag képezhető 5 kg cukorból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "3c410561-e803-4bae-bee7-54b9635d066b", "text": "Egy 6 méteres szalagból 3/4 méteres darabokat vágunk. Hány darabot kapunk? (6 : 3/4 = 6 * 4/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "d6a36c85-1cb5-4f9d-b17c-283cb7c50f93", "text": "Törtek osztásakor az eredmény lehet nagyobb az eredeti osztandónál, ha az osztó 1-nél kisebb tört.", "type": "true-false", "options": [{"id": "13bd41f0-a3d2-4210-8086-1a7baa732669", "text": "Igaz", "isCorrect": true}, {"id": "75f80628-c42d-481b-921e-82b623b0c787", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "10d9e530-f02e-486f-8eaf-cb1b1fa442ea", "text": "Hány 1/5 méteres darab vágható ki 2 méter anyagból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "31a6257b-3d82-4943-a326-31d7c7a607e6", "text": "A szöveges feladatoknál az adatok lejegyzése és a mértékegységek egyeztetése elengedhetetlen.", "type": "true-false", "options": [{"id": "064a5168-e057-4ff8-a02e-5a4ab92c9f47", "text": "Igaz", "isCorrect": true}, {"id": "d14526de-a72e-46df-badc-fe16d9e5352f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c84dc280-8c35-424a-a783-b693738779d9", "text": "Mennyi 4 : 2/3? (4 * 3/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('50f074cc-7dce-4a8e-b02e-95f8a940bab3', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$34. óra: Gyakorlóóra$q$, $q$A törtek szorzásának és osztásának rögzítése, feladatok gyakorlása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "45368360-72d5-4d04-b8db-2b23f67384ab", "text": "Mennyi 3/5 * 5/3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "fa0c23ee-044f-4bfd-a6a3-40f95c783e87", "text": "Mennyi 4/7 : 2/7? (4/7 * 7/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "a1f318b8-6a1c-4c32-9dbf-e3835f4b58b8", "text": "Melyik állítás igaz?", "type": "multiple-choice", "options": [{"id": "af3248d8-3ce3-452c-a0be-18ae0fa72399", "text": "Két 1-nél kisebb pozitív tört szorzata kisebb mindkét tényezőnél", "isCorrect": true}, {"id": "573ff29b-1748-4855-910d-eba49f060639", "text": "A szorzat mindig nagyobb a tényezőknél", "isCorrect": false}, {"id": "8d4807a0-9fe4-4285-bb77-f0de0f33f847", "text": "Az osztás mindig kisebb számot ad", "isCorrect": false}, {"id": "4c3806a8-d02f-4b68-8c21-91a89440c23a", "text": "Nincs reciproka a 4/5-nek", "isCorrect": false}], "timeLimit": 15}, {"id": "596feffa-e1b2-4737-8cb4-47c01cd6a59a", "text": "Mennyi 5/6 * 12? (5 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "3c784864-98d8-4141-bad1-75137e9a3fcc", "text": "A 2/3 osztva 1/3-dal 2-t ad.", "type": "true-false", "options": [{"id": "6870292c-8264-417d-acd7-e72fafda2571", "text": "Igaz", "isCorrect": true}, {"id": "7ac862e3-7026-44fb-9bdb-078e9ce0cdf2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bfd34b20-bccc-452c-a764-6d17d7cb5859", "text": "Mennyi 3/8 : 3/8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "2f05a50b-845f-4b7f-957d-a38b52ceda41", "text": "Mennyi 1/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "e40e02a9-9db2-44e6-9797-d72168663e72", "text": "1/5", "isCorrect": true}, {"id": "37d363f9-862c-4fbb-8141-42548d9fde08", "text": "4/20", "isCorrect": false}, {"id": "e3b35d61-2cd0-4b5f-ab74-e62699ac472e", "text": "1/20", "isCorrect": false}, {"id": "38ca3fd4-1e30-4825-a43a-5f8ac6e7251e", "text": "4/9", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5ba686ae-d351-486a-8636-e549d313434d', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$35. óra: Számonkérés$q$, $q$Számonkérés a közönséges törtek műveleteiből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "91f9d4c8-114b-4335-b72d-5c5ed8b7658f", "text": "1. Mennyi 2/5 + 1/5?", "type": "multiple-choice", "options": [{"id": "50a97c19-ec2d-47ac-834a-92fee824993b", "text": "3/5", "isCorrect": true}, {"id": "9a6e20b6-b25d-406b-a143-dcfa17706563", "text": "3/10", "isCorrect": false}, {"id": "5ac954f8-7696-4249-88fa-34a4e4c071fd", "text": "2/10", "isCorrect": false}, {"id": "4d80b7dd-7253-4614-9444-346e45de1d34", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "30b8454b-cddb-40d0-be26-7a4356d5e357", "text": "2. Mennyi 3/4 - 1/2? (3/4 - 2/4)", "type": "multiple-choice", "options": [{"id": "021349ff-7118-438b-83d4-05b4a94cefd5", "text": "1/4", "isCorrect": true}, {"id": "c9f3c8d0-779c-409a-bcea-891ea16ec984", "text": "2/2", "isCorrect": false}, {"id": "e92db49d-a77a-49b4-a7ce-0ea2822d7e08", "text": "1/2", "isCorrect": false}, {"id": "4e5c6d40-8f90-4ed6-9a56-7634e70ab16c", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "472a4e1f-d9bf-4a81-9813-4e1f768fe0d2", "text": "3. Mennyi 2/3 * 3/4?", "type": "multiple-choice", "options": [{"id": "04c0e4a9-59e0-4e20-ad8a-5134592fb6aa", "text": "6/12 (azaz 1/2)", "isCorrect": true}, {"id": "a450151b-1099-4eef-9306-567f0a29cea8", "text": "5/7", "isCorrect": false}, {"id": "8b6817a6-e653-45e6-bed4-1733c31806c9", "text": "6/7", "isCorrect": false}, {"id": "3fa951ca-dbca-4fff-bc12-c4d7513cf222", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "e1eb28b4-46aa-4f36-ba97-37be1d76dc94", "text": "4. Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "46b06a91-f0bd-4102-9f21-ed22e8df0d03", "text": "5. Mi a 7/8 reciproka?", "type": "multiple-choice", "options": [{"id": "c20e674b-7220-42b6-9428-46e2a1c9087f", "text": "8/7", "isCorrect": true}, {"id": "19a6945d-1dbc-434b-b473-3ee3afaff8f8", "text": "-7/8", "isCorrect": false}, {"id": "36e8ff52-e17c-4058-a008-a47f06f472fc", "text": "1/7", "isCorrect": false}, {"id": "3714e26e-347d-4e85-9ecb-f3ad22836083", "text": "7/8", "isCorrect": false}], "timeLimit": 15}, {"id": "39f08a2c-052f-4f24-a627-c387ae69182c", "text": "6. Mennyi 40-nek a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "1b1c1b5e-d4ec-4999-bd36-f4a6f8853a69", "text": "7. Egy szám és reciproka szorzata 1.", "type": "true-false", "options": [{"id": "d3c601dd-5a13-475d-bd2a-c7c430f527bd", "text": "Igaz", "isCorrect": true}, {"id": "0c5d0902-919a-42f9-bfaf-f7dc69e264b1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b7bf12e3-9fd3-497f-a026-fc81842a74d4", "text": "8. Mennyi 5 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e7d4144a-2a22-4612-98a0-78a0f0b38406", "text": "9. A törtek szorzásakor a számlálót a számlálóval, a nevezőt a nevezővel szorozzuk.", "type": "true-false", "options": [{"id": "1a754978-c1a2-4109-9835-c5ff651b4415", "text": "Igaz", "isCorrect": true}, {"id": "c55a1987-e2a0-45e4-97de-8227f7be79df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b305a9b3-9969-496f-aefb-1e704bbfe3bd", "text": "10. Hány negyedből áll 3 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fe106ecf-00c0-4e54-9a4f-2e671c23b429', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$36. óra: Matematikai játékok$q$, $q$Matematikai társasjátékok, stratégiák törtekkel, csoport- és páros munka.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "090280ef-77cb-4cb9-94b3-a1c5f1edca1d", "text": "Melyik állítás igaz a matematikai társasjátékokról?", "type": "multiple-choice", "options": [{"id": "3ca3c054-dd34-44ce-a16d-2cf1059879b4", "text": "Fejlesztik a számolási gyorsaságot és a logikai stratégiát", "isCorrect": true}, {"id": "3a69c4f8-4be9-417d-81c4-22dc597ae777", "text": "Nincs közük a matematikához", "isCorrect": false}, {"id": "d904a68a-c60b-460b-9bc0-20653389eb68", "text": "Kizárólag szerencse kell hozzájuk", "isCorrect": false}, {"id": "12643714-0154-4507-8d7a-11e429ce726d", "text": "Tiltható az együttműködés", "isCorrect": false}], "timeLimit": 15}, {"id": "b6496f01-8242-4824-bd54-d5a0aa1f397e", "text": "A tört domino játékban az egyenlő értékű törteket illesztjük össze.", "type": "true-false", "options": [{"id": "0556713e-3184-4f28-bbe8-ae5feab9a8e3", "text": "Igaz", "isCorrect": true}, {"id": "05d8be9f-0c28-4b2f-bc7f-1f3fd389a60b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "21fcc464-3fe9-4050-ba4d-84b5b5215acd", "text": "Melyik tört felel meg a 0,5 tizedes törtnek?", "type": "multiple-choice", "options": [{"id": "f1f56171-a11e-4cca-aed1-7f2a0a6780d8", "text": "1/2", "isCorrect": true}, {"id": "f9bd09b2-5096-4f76-b407-8fc8b29b708f", "text": "1/5", "isCorrect": false}, {"id": "2b7d1f1b-24cd-46cd-9689-92330b5f5561", "text": "2/5", "isCorrect": false}, {"id": "422e6207-e19f-44af-818d-2e717b2c5e77", "text": "5/2", "isCorrect": false}], "timeLimit": 15}, {"id": "6b60b460-5fe8-4a45-adff-b79f603b9101", "text": "Melyik tört felel meg a 0,25-nek?", "type": "multiple-choice", "options": [{"id": "791cb2d3-880b-43ed-9dea-30f6d715d14f", "text": "1/4", "isCorrect": true}, {"id": "93433db4-ed54-405c-9ccb-12938a9b369e", "text": "1/2", "isCorrect": false}, {"id": "16009b2e-3d66-48b1-93e2-96d3f26cc444", "text": "2/5", "isCorrect": false}, {"id": "ecffe05a-f34d-40aa-9d45-f3fbd63d9faa", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "cbbdaa5c-418a-49a8-b133-54f41fbbf19f", "text": "A 3/4 tizedes tört alakja 0,75.", "type": "true-false", "options": [{"id": "8179d1ba-ede9-4f36-beb2-685653be3b5c", "text": "Igaz", "isCorrect": true}, {"id": "c4a09214-414a-44cc-b135-f168f0e7a06e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "acb69424-d153-45da-abf5-428d85c46b49", "text": "Mennyi 0,2 közönséges tört alakban legegyszerűbb formában?", "type": "multiple-choice", "options": [{"id": "4f14d717-2f4e-4d3f-8570-1108e731ee5b", "text": "1/5", "isCorrect": true}, {"id": "eb950aef-bd7c-45f8-bbb0-4735111a0062", "text": "2/10", "isCorrect": false}, {"id": "ee4c0867-14d7-4d9a-96a8-741301a74b8e", "text": "1/2", "isCorrect": false}, {"id": "219ffc62-812f-49f0-aa5a-d648fc97591f", "text": "2/5", "isCorrect": false}], "timeLimit": 15}, {"id": "533c4cb4-8091-43b0-b0db-567726b3a0f2", "text": "A tört-bingó játékban a válaszok gyors és pontos kiszámítása a nyerő stratégia.", "type": "true-false", "options": [{"id": "a1994abd-5de5-4ac8-af14-837f5f17a817", "text": "Igaz", "isCorrect": true}, {"id": "8c235661-4e5a-4af0-9e39-fc8ff0c1f6a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e0ac05e9-2636-4b5c-a75d-6b511fa78368', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$37. óra: Mit tanultunk a tizedes törtekről?$q$, $q$Tizedes törtek helyi értékei, összeadása és kivonása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "46fddc16-7dec-4c6a-bbd9-4fb40ae9a8a5", "text": "Mi a tizedesvessző utáni első helyi érték neve?", "type": "multiple-choice", "options": [{"id": "29b5a42e-6f7c-4429-8295-e76e63b76768", "text": "Tizedek", "isCorrect": true}, {"id": "f9285940-97d3-40e3-942d-0d45c5f0e0b2", "text": "Századok", "isCorrect": false}, {"id": "cfa83066-767a-4785-a529-e7f3645bb994", "text": "Ezredeket", "isCorrect": false}, {"id": "c6b60a00-7370-4327-b95d-da19ef761957", "text": "Egyesek", "isCorrect": false}], "timeLimit": 15}, {"id": "51d44cea-9026-41e7-9489-1ddc33f076a9", "text": "Mi a tizedesvessző utáni második helyi érték neve?", "type": "multiple-choice", "options": [{"id": "b8ce4ea6-0a4e-4c3f-9b81-dc92bc524820", "text": "Századok", "isCorrect": true}, {"id": "815d0eec-397d-44d2-adda-19144a24c6a3", "text": "Tizedek", "isCorrect": false}, {"id": "98d559e2-9cea-4412-a905-f5e73fb1d8a7", "text": "Ezredek", "isCorrect": false}, {"id": "b1b71c47-db4e-4e14-8f71-687ac89b1cb7", "text": "Tízesek", "isCorrect": false}], "timeLimit": 15}, {"id": "b2fc193e-a900-45ee-9053-b35fabb7cdd5", "text": "Mennyi 3,45 + 2,13?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5.58"}, {"id": "3e1ef704-daa6-4f91-aa89-1ddd3f487c63", "text": "Mennyi 7,8 - 3,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.3"}, {"id": "575048d8-c871-4dc6-801b-60375fd61409", "text": "Tizedes törtek írásbeli összeadásakor a tizedesvesszőknek egymás alá kell kerülniük.", "type": "true-false", "options": [{"id": "407cffec-de8d-4309-86fb-a38e028878a9", "text": "Igaz", "isCorrect": true}, {"id": "024bdb17-8900-4d18-9fa8-9a88161bdeab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5b3b737e-71dc-4c31-9ff3-9693e10ffbde", "text": "Mennyi 5,6 + 4,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "31caaa2a-3ee1-4f5a-850a-4214c2b796e1", "text": "Melyik szám nagyobb: 4,05 vagy 4,5?", "type": "multiple-choice", "options": [{"id": "528f18d4-676a-4a75-90f4-317f36d618a1", "text": "4,5 (mert 4,5 = 4,50)", "isCorrect": true}, {"id": "1df2863f-f109-4415-bc52-2a0d59248125", "text": "4,05", "isCorrect": false}, {"id": "3b3a6ffd-d88e-489c-a4bc-3644608d73ae", "text": "Egyenlőek", "isCorrect": false}, {"id": "7a151496-d684-4867-a588-16ec4b4c96af", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e64e1141-df38-4019-a15e-692d6a1f51e2', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$38. óra: Szorzás tizedes törttel$q$, $q$Tizedes tört szorzása egész számmal és tizedes törttel, vesszőhely meghatározása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "ccf1b446-dfd3-4c36-a207-fb71e991d5b0", "text": "Hogyan határozzuk meg a tizedesjegyek számát két tizedes tört szorzatában?", "type": "multiple-choice", "options": [{"id": "3e923101-e7c6-4f83-b1df-8dd1e2481134", "text": "A tényezők tizedesjegyeinek számát összeadjuk", "isCorrect": true}, {"id": "2b408644-db79-4503-baa5-5d7a6d335557", "text": "A nagyobbik tényező tizedesjegyeit vesszük", "isCorrect": false}, {"id": "78639b6e-f6ca-42ae-977d-d3ae2ed3aa81", "text": "Mindig 1 tizedesjegy lesz", "isCorrect": false}, {"id": "4b7cc07a-5cb8-492d-945a-5d4c07a340b9", "text": "Nem lesz tizedesjegy", "isCorrect": false}], "timeLimit": 15}, {"id": "1729e1de-443a-4880-8e38-9c44ab96e627", "text": "Mennyi 0,3 * 0,2? (3*2 = 6, 2 tizedesjegy)", "type": "multiple-choice", "options": [{"id": "70d86d3b-3447-4458-a48b-7662b21008b7", "text": "0,06", "isCorrect": true}, {"id": "13ad0ab1-9411-40d3-afa4-24deedbb6645", "text": "0,6", "isCorrect": false}, {"id": "f381b90b-0841-4d0f-adc8-7c3f3774b752", "text": "6,0", "isCorrect": false}, {"id": "8c5698d1-9929-416e-b652-23d444b222bd", "text": "0,006", "isCorrect": false}], "timeLimit": 15}, {"id": "30fe9da7-a1f5-4d5a-aefb-b57772f376e9", "text": "Mennyi 2,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "156df6b1-0a25-43a6-8a7c-0d3fb58669c6", "text": "Mennyi 1,2 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "b2610967-c55c-4720-97e2-4d2c7c2e8778", "text": "Ha egy tizedes törtet 10-zel szorzunk, a tizedesvessző egy hellyel jobbra lép.", "type": "true-false", "options": [{"id": "4af99def-a98f-4dc0-b9b4-536ccb27cbad", "text": "Igaz", "isCorrect": true}, {"id": "5e82cc54-32a7-4ffa-ace5-e3e6b7621761", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "25751386-ec65-4883-8e15-36d5a9d56856", "text": "Mennyi 3,45 * 100?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "345"}, {"id": "27a49219-b6ad-49a1-80bc-f1b8df262a0e", "text": "Mennyi 0,1 * 0,1?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.01"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ccae8afa-cbd9-43da-a447-dab77a9f430b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$39. óra: Osztás tizedes törttel$q$, $q$Tizedes törttel való osztás szabálya, osztó egész számmá alakítása (bővítés 10-zel, 100-zal).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "a156603a-ef4f-4fd2-bdfa-96394335cc16", "text": "Mit teszünk tizedes törttel való osztáskor először?", "type": "multiple-choice", "options": [{"id": "ba905633-d9e6-4752-bbf2-939db77a398b", "text": "Az osztandót és az osztót is megszorozzuk 10-zel/100-zal, hogy az osztó egész szám legyen", "isCorrect": true}, {"id": "890519d9-4204-440c-9f98-ecdce8685d47", "text": "Elhagyjuk a tizedesvesszőt az osztandóból", "isCorrect": false}, {"id": "fa95ab16-7e03-40ea-9c50-e17ff54b57a2", "text": "Kivonjuk az osztót az osztandóból", "isCorrect": false}, {"id": "def085e0-bb34-4d7e-aa5d-35cae5fd865c", "text": "Csak az osztót szorozzuk meg", "isCorrect": false}], "timeLimit": 15}, {"id": "330df4f9-0c1e-41d8-8c81-0740065b10fc", "text": "Mennyi 2,4 : 0,6? (24 : 6)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "5e479bb9-bdc0-4cde-a7f4-750501571013", "text": "Mennyi 1,5 : 0,3? (15 : 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "32884057-ffaa-461c-bf0f-eb5377a84dda", "text": "Ha egy tizedes törtet 10-zel osztunk, a tizedesvessző 1 hellyel balra lép.", "type": "true-false", "options": [{"id": "5ce98686-ccab-4c6d-9303-0481ab509784", "text": "Igaz", "isCorrect": true}, {"id": "f1ee75b8-1081-4980-9e41-e7c0bc350d84", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d8170cbd-297e-4d12-8e17-809233980b16", "text": "Mennyi 45,6 : 10?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.56"}, {"id": "13bda6fb-f9d3-4c81-bafe-3b4766ff0893", "text": "Mennyi 3,6 : 0,1? (36 : 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "dd29acce-77d3-4af8-b2f7-b1b5051a2153", "text": "A tizedes törttel való osztást ellenőrizhetjük szorzással.", "type": "true-false", "options": [{"id": "f2b3e5df-e2ab-4955-9074-1d4e25fff1aa", "text": "Igaz", "isCorrect": true}, {"id": "c3a27822-81dc-45b1-a7eb-d7f32cc58903", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c6ab0a54-1d0c-4236-bf95-83ec380011ca', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával$q$, $q$Vásárlási, mértékegységes és szöveges feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "7eb25ded-135c-44f4-a0ab-cb0c0d741b24", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "24632a4d-3ff4-4ec0-8ff0-00b4eb75221e", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "2d00215f-373c-4eb7-b8b7-3c551a0cb957", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "19d1e9b0-0835-4092-aac4-67f3d1be9327", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "302a00ec-358c-4146-809d-705634b26fed", "text": "Igaz", "isCorrect": true}, {"id": "a2f880ab-db19-4fe3-9d0f-2547bf2ea3a6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "69f87e34-bd8a-4a3d-aed6-36c01b70ee27", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "f7f86426-7401-4643-8d2a-d223df237bff", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "fe02ba1c-7756-42b7-bccc-24658e6add11", "text": "Igaz", "isCorrect": true}, {"id": "d959cd6c-f54d-4c1a-b730-4d49022c6d07", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c1a94ac1-8768-4787-9f80-633e9d75660c", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;